func (s *Server) importDocument(w http.ResponseWriter, r *http.Request) {
	p, _ := principalFrom(r.Context())
	all, err := s.settings.GetAll(r.Context(), false)
	if err != nil {
		writeError(w, 500, "SETTINGS_ERROR", "업로드 설정을 불러오지 못했습니다.")
		return
	}
	maxBytes := int64(all.Security.MaxUploadMB) << 20
	r.Body = http.MaxBytesReader(w, r.Body, maxBytes+(1<<20))
	if err := r.ParseMultipartForm(maxBytes); err != nil {
		writeError(w, 413, "FILE_TOO_LARGE", fmt.Sprintf("파일은 %dMB 이하여야 합니다.", all.Security.MaxUploadMB))
		return
	}
	workspaceID, err := uuid.Parse(r.FormValue("workspaceId"))
	if err != nil {
		writeError(w, 400, "WORKSPACE_REQUIRED", "워크스페이스가 필요합니다.")
		return
	}
	var memberRole, workspaceKind string
	if s.db.QueryRow(r.Context(), `SELECT wm.role,w.kind FROM workspace_members wm JOIN workspaces w ON w.id=wm.workspace_id WHERE wm.workspace_id=$1 AND wm.user_id=$2`, workspaceID, p.User.ID).Scan(&memberRole, &workspaceKind) != nil || memberRole == "VIEWER" {
		writeError(w, 403, "WORKSPACE_PERMISSION_DENIED", "이 워크스페이스로 가져올 권한이 없습니다.")
		return
	}
	var folderID *uuid.UUID
	if value := strings.TrimSpace(r.FormValue("folderId")); value != "" {
		parsed, parseErr := uuid.Parse(value)
		if parseErr != nil {
			writeError(w, 400, "INVALID_FOLDER", "폴더 식별자가 올바르지 않습니다.")
			return
		}
		var validFolder bool
		_ = s.db.QueryRow(r.Context(), `SELECT EXISTS(SELECT 1 FROM folders WHERE id=$1 AND workspace_id=$2 AND deleted_at IS NULL)`, parsed, workspaceID).Scan(&validFolder)
		if !validFolder {
			writeError(w, 400, "INVALID_FOLDER", "워크스페이스에 속한 폴더를 선택해 주세요.")
			return
		}
		folderID = &parsed
	}
	file, header, err := r.FormFile("file")
	if err != nil {
		writeError(w, 400, "FILE_REQUIRED", "가져올 파일이 필요합니다.")
		return
	}
	defer file.Close()
	body, err := io.ReadAll(io.LimitReader(file, maxBytes+1))
	if err != nil || int64(len(body)) > maxBytes {
		writeError(w, 413, "FILE_TOO_LARGE", "파일 크기 제한을 초과했습니다.")
		return
	}
	extension := strings.ToLower(filepath.Ext(header.Filename))
	if extension == "" {
		extension = extensionFromMediaType(header.Header.Get("Content-Type"), body)
	}
	documentID := uuid.New()
	parsed, err := parseUpload(r.Context(), extension, body)
	if errors.Is(err, errUnsupportedUpload) {
		writeError(w, 400, "UNSUPPORTED_IMPORT", err.Error())
		return
	}
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "파일 내용을 읽지 못했습니다: "+err.Error())
		return
	}
	content, assets, embeddedTitle, furniture := parsed.content, parsed.assets, parsed.title, parsed.furniture
	// Imported images become attachments so the editor can render them and
	// the export path can embed them again.
	attachments, content, err := prepareImportedAssets(assets, content)
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
		return
	}
	// An imported document has never been through the editor, so stamp the
	// block identities that comments, citations and diffs anchor to.
	content, err = withBlockIDs(content)
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
		return
	}
	if !validDocumentJSON(content) {
		writeError(w, 400, "IMPORT_TOO_LARGE", "가져온 문서가 너무 큽니다. 파일을 나눠서 가져와 주세요.")
		return
	}
	title := strings.TrimSpace(r.FormValue("title"))
	if title == "" {
		title = strings.TrimSpace(embeddedTitle)
	}
	if title == "" {
		title = strings.TrimSuffix(filepath.Base(header.Filename), filepath.Ext(header.Filename))
	}
	if title == "" {
		title = "가져온 문서"
	}
	title = truncateRunes(title, 240)
	// A Markdown or HTML file muni exported carries its title as the first
	// heading; now that the title is decided, that echo leaves the body —
	// before the search text is taken from it, so the title is not indexed
	// twice.
	if parsed.titleInBody {
		content, err = dropLeadingTitle(content, title)
		if err != nil {
			writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
			return
		}
	}
	text := extractDocumentText(content)
	visibility := "RESTRICTED"
	if workspaceKind != "PERSONAL" {
		visibility = "WORKSPACE"
	}
	err = s.storeImportedDocument(r.Context(), importedDocument{
		id: documentID, workspaceID: workspaceID, folderID: folderID, ownerID: p.User.ID,
		title: title, visibility: visibility, content: content, text: text, furniture: furniture,
		reason: "import:" + strings.TrimPrefix(extension, "."), attachments: attachments,
	})
	if err != nil {
		writeError(w, 500, "IMPORT_FAILED", "가져온 문서를 저장하지 못했습니다.")
		return
	}
	s.audit(r, &p.User.ID, "IMPORT_DOCUMENT", "DOCUMENT", &documentID, map[string]any{"format": strings.TrimPrefix(extension, "."), "bytes": len(body), "images": len(attachments)})
	s.getDocumentByID(w, r, documentID)
}

// importedDocument is a document about to be created from a file: what the
// row needs, the reason its first revision records, and the pictures that
// become its attachments.
type importedDocument struct {
	id          uuid.UUID
	workspaceID uuid.UUID
	folderID    *uuid.UUID
	ownerID     uuid.UUID
	title       string
	visibility  string
	content     json.RawMessage
	text        string
	furniture   docx.Meta
	reason      string
	attachments []importedAttachment
}

// storeImportedDocument writes the document, its first revision and its
// attachments in one transaction, for the upload that makes a document and
// the handoff that takes one from another service.
func (s *Server) storeImportedDocument(ctx context.Context, doc importedDocument) error {
	return database.WithTx(ctx, s.db, func(tx pgx.Tx) error {
		if _, err := tx.Exec(ctx, `INSERT INTO documents(id,workspace_id,folder_id,owner_id,title,visibility,content_json,content_text,revision_no,page_header,page_footer,page_orientation) VALUES($1,$2,$3,$4,$5,$6,$7,$8,1,$9,$10,$11)`,
			doc.id, doc.workspaceID, doc.folderID, doc.ownerID, doc.title, doc.visibility, doc.content, doc.text,
			truncateRunes(doc.furniture.Header, 200), truncateRunes(doc.furniture.Footer, 200), orientationOf(doc.furniture.Landscape)); err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `INSERT INTO document_revisions(document_id,revision_no,content_json,content_text,author_id,reason) VALUES($1,1,$2,$3,$4,$5)`, doc.id, doc.content, doc.text, doc.ownerID, doc.reason); err != nil {
			return err
		}
		for _, attachment := range doc.attachments {
			sum := sha256.Sum256(attachment.Data)
			if _, err := tx.Exec(ctx, `INSERT INTO attachments(id,document_id,uploader_id,name,media_type,size_bytes,sha256,data) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
				attachment.ID, doc.id, doc.ownerID, truncateRunes(attachment.Name, 240), attachment.MediaType, len(attachment.Data), hex.EncodeToString(sum[:]), attachment.Data); err != nil {
				return err
			}
		}
		return nil
	})
}

// upload is what a document file turns into: the content, the pictures it
// carried, the title it held in itself and what it said about the paper.
type upload struct {
	content   json.RawMessage
	assets    []richdoc.Asset
	title     string
	furniture docx.Meta
	// titleInBody says the file is a format whose first heading may be the
	// title written into the body by muni's own Markdown or HTML export
	// (dropLeadingTitle).
	titleInBody bool
}

var errUnsupportedUpload = errors.New("지원 형식은 PDF, DOCX, HWP, HWPX, Markdown, TXT, HTML입니다.")

// parseUpload reads a document file by its extension. It is the one place
// that knows which parser reads what, for the import that makes a document
// and the one that puts a file into a document already open.
func parseUpload(ctx context.Context, extension string, body []byte) (upload, error) {
	var content json.RawMessage
	var assets []richdoc.Asset
	embeddedTitle := ""
	var furniture docx.Meta
	var err error
	titleInBody := false
	switch extension {
	case ".txt":
		content, err = plainTextDocument(string(body))
	case ".md", ".markdown":
		content, assets, err = markdownDocument(string(body))
		titleInBody = true
	case ".html", ".htm":
		content, assets, err = htmlDocument(body)
		titleInBody = true
	case ".docx":
		content, assets, furniture, err = docxImport(body)
	case ".hwpx":
		content, assets, furniture, err = hwpxImport(body)
	case ".hwp":
		content, assets, furniture, err = hwpImport(body)
	case ".pdf":
		// PDF interpretation is CPU bound; bound it so one upload cannot hold
		// a worker for the whole request timeout.
		parseCtx, cancelParse := context.WithTimeout(ctx, 90*time.Second)
		content, assets, embeddedTitle, err = pdfImport(parseCtx, body)
		cancelParse()
	default:
		return upload{}, errUnsupportedUpload
	}
	if err != nil {
		return upload{}, err
	}
	return upload{content: content, assets: assets, title: embeddedTitle, furniture: furniture, titleInBody: titleInBody}, nil
}

// importIntoDocument reads a file dropped on an open document and returns
// its content for the editor to put where it was dropped. The pictures
// become attachments of this document now, so the content refers to them
// the way a saved document does; the words are the editor's to place and
// save, in one step that undo takes back.
func (s *Server) importIntoDocument(w http.ResponseWriter, r *http.Request) {
	documentID, ok := pathUUID(w, r, "id")
	if !ok {
		return
	}
	p, _ := principalFrom(r.Context())
	role, err := s.documentRole(r.Context(), p.User, documentID, false)
	if !documentAllowed(w, role, err, "EDITOR") {
		return
	}
	all, err := s.settings.GetAll(r.Context(), false)
	if err != nil {
		writeError(w, 500, "SETTINGS_ERROR", "업로드 설정을 불러오지 못했습니다.")
		return
	}
	maxBytes := int64(all.Security.MaxUploadMB) << 20
	r.Body = http.MaxBytesReader(w, r.Body, maxBytes+(1<<20))
	if err := r.ParseMultipartForm(maxBytes); err != nil {
		writeError(w, 413, "FILE_TOO_LARGE", fmt.Sprintf("파일은 %dMB 이하여야 합니다.", all.Security.MaxUploadMB))
		return
	}
	file, header, err := r.FormFile("file")
	if err != nil {
		writeError(w, 400, "FILE_REQUIRED", "가져올 파일이 필요합니다.")
		return
	}
	defer file.Close()
	body, err := io.ReadAll(io.LimitReader(file, maxBytes+1))
	if err != nil || int64(len(body)) > maxBytes {
		writeError(w, 413, "FILE_TOO_LARGE", "파일 크기 제한을 초과했습니다.")
		return
	}
	extension := strings.ToLower(filepath.Ext(header.Filename))
	if extension == "" {
		extension = extensionFromMediaType(header.Header.Get("Content-Type"), body)
	}
	parsed, err := parseUpload(r.Context(), extension, body)
	if errors.Is(err, errUnsupportedUpload) {
		writeError(w, 400, "UNSUPPORTED_IMPORT", err.Error())
		return
	}
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "파일 내용을 읽지 못했습니다: "+err.Error())
		return
	}
	attachments, content, err := prepareImportedAssets(parsed.assets, parsed.content)
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
		return
	}
	content, err = withBlockIDs(content)
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
		return
	}
	if !validDocumentJSON(content) {
		writeError(w, 400, "IMPORT_TOO_LARGE", "가져온 문서가 너무 큽니다. 파일을 나눠서 가져와 주세요.")
		return
	}
	err = database.WithTx(r.Context(), s.db, func(tx pgx.Tx) error {
		for _, attachment := range attachments {
			sum := sha256.Sum256(attachment.Data)
			if _, err := tx.Exec(r.Context(), `INSERT INTO attachments(id,document_id,uploader_id,name,media_type,size_bytes,sha256,data) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
				attachment.ID, documentID, p.User.ID, truncateRunes(attachment.Name, 240), attachment.MediaType, len(attachment.Data), hex.EncodeToString(sum[:]), attachment.Data); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		writeError(w, 500, "IMPORT_FAILED", "가져온 그림을 저장하지 못했습니다.")
		return
	}
	title := strings.TrimSpace(parsed.title)
	if title == "" {
		title = strings.TrimSuffix(filepath.Base(header.Filename), filepath.Ext(header.Filename))
	}
	s.audit(r, &p.User.ID, "IMPORT_INTO_DOCUMENT", "DOCUMENT", &documentID, map[string]any{"format": strings.TrimPrefix(extension, "."), "bytes": len(body), "images": len(attachments)})
	writeData(w, 200, map[string]any{
		"content":   content,
		"title":     truncateRunes(title, 240),
		"header":    truncateRunes(parsed.furniture.Header, 200),
		"footer":    truncateRunes(parsed.furniture.Footer, 200),
		"landscape": parsed.furniture.Landscape,
		"format":    strings.TrimPrefix(extension, "."),
		"images":    len(attachments),
	})
}

package httpapi

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"strconv"
	"strings"

	"github.com/hkjang/muni/internal/richdoc"
	xhtml "golang.org/x/net/html"
	"golang.org/x/net/html/atom"
)

type dataURIImage struct {
	mediaType string
	data      []byte
}

// decodeDataURIImage extracts the bytes of a base64 data: URI image.
func decodeDataURIImage(value string) (dataURIImage, bool) {
	if !strings.HasPrefix(value, "data:image/") {
		return dataURIImage{}, false
	}
	comma := strings.Index(value, ",")
	if comma < 0 {
		return dataURIImage{}, false
	}
	meta := value[len("data:"):comma]
	if !strings.Contains(meta, "base64") {
		return dataURIImage{}, false
	}
	mediaType := strings.ToLower(strings.SplitN(meta, ";", 2)[0])
	if !safeInlineImageType(mediaType) {
		return dataURIImage{}, false
	}
	payload := strings.NewReplacer("\n", "", "\r", "", " ", "").Replace(value[comma+1:])
	data, err := base64.StdEncoding.DecodeString(payload)
	if err != nil || len(data) == 0 {
		return dataURIImage{}, false
	}
	return dataURIImage{mediaType: mediaType, data: data}, true
}

func imageAssetName(alt, mediaType string) string {
	name := strings.TrimSpace(alt)
	if name == "" {
		name = "image"
	}
	name = strings.Map(func(r rune) rune {
		if r == '/' || r == '\\' || r < 0x20 {
			return -1
		}
		return r
	}, name)
	extension := ".png"
	switch mediaType {
	case "image/jpeg":
		extension = ".jpg"
	case "image/gif":
		extension = ".gif"
	case "image/webp":
		extension = ".webp"
	}
	if strings.HasSuffix(strings.ToLower(name), extension) {
		return truncateRunes(name, 200)
	}
	return truncateRunes(name, 200) + extension
}

// htmlDocument converts an HTML file into a document, keeping headings, lists,
// tables, inline formatting, links and inline images. Script and style content
// never reaches the output.
func htmlDocument(body []byte) (json.RawMessage, []richdoc.Asset, error) {
	root, err := xhtml.Parse(bytes.NewReader(body))
	if err != nil {
		return nil, nil, err
	}
	converter := &htmlConverter{inline: &inlineContext{}}
	start := findHTMLBody(root)
	blocks := converter.blocks(childrenOf(start), 0)
	if len(blocks) == 0 {
		if text := strings.TrimSpace(visibleText(start)); text != "" {
			blocks = append(blocks, richdoc.Paragraph(richdoc.Text(text)))
		}
	}
	document := richdoc.Doc(blocks...)
	richdoc.LiftImages(document)
	content, err := document.JSON()
	if err != nil {
		return nil, nil, err
	}
	return content, converter.inline.assets, nil
}

func findHTMLBody(root *xhtml.Node) *xhtml.Node {
	var found *xhtml.Node
	var walk func(*xhtml.Node)
	walk = func(node *xhtml.Node) {
		if found != nil {
			return
		}
		if node.Type == xhtml.ElementNode && node.DataAtom == atom.Body {
			found = node
			return
		}
		for child := node.FirstChild; child != nil; child = child.NextSibling {
			walk(child)
		}
	}
	walk(root)
	if found == nil {
		return root
	}
	return found
}

func childrenOf(node *xhtml.Node) []*xhtml.Node {
	if node == nil {
		return nil
	}
	out := make([]*xhtml.Node, 0, 8)
	for child := node.FirstChild; child != nil; child = child.NextSibling {
		out = append(out, child)
	}
	return out
}

func visibleText(node *xhtml.Node) string {
	if node == nil {
		return ""
	}
	if node.Type == xhtml.TextNode {
		return node.Data
	}
	if node.Type == xhtml.ElementNode && isIgnoredHTMLElement(node.Data) {
		return ""
	}
	var out strings.Builder
	for child := node.FirstChild; child != nil; child = child.NextSibling {
		out.WriteString(visibleText(child))
	}
	return out.String()
}

func isIgnoredHTMLElement(name string) bool {
	switch strings.ToLower(name) {
	case "script", "style", "head", "title", "meta", "link", "noscript", "template",
		"iframe", "object", "embed", "svg", "canvas", "audio", "video", "form", "select", "textarea", "button":
		return true
	}
	return false
}

const maxHTMLDepth = 24

type htmlConverter struct {
	inline *inlineContext
}

func htmlAttr(node *xhtml.Node, name string) string {
	if node == nil {
		return ""
	}
	for _, attribute := range node.Attr {
		if strings.EqualFold(attribute.Key, name) {
			return attribute.Val
		}
	}
	return ""
}

func (h *htmlConverter) blocks(nodes []*xhtml.Node, depth int) []*richdoc.Node {
	out := make([]*richdoc.Node, 0, len(nodes))
	pending := make([]*xhtml.Node, 0, 4)
	flush := func() {
		if len(pending) == 0 {
			return
		}
		if inline := h.inlineNodes(pending, nil, depth); len(inline) > 0 {
			out = append(out, richdoc.Paragraph(inline...))
		}
		pending = pending[:0]
	}
	for _, node := range nodes {
		if node == nil {
			continue
		}
		if node.Type == xhtml.CommentNode || node.Type == xhtml.DoctypeNode {
			continue
		}
		if node.Type == xhtml.TextNode {
			if strings.TrimSpace(node.Data) != "" {
				pending = append(pending, node)
			}
			continue
		}
		if node.Type != xhtml.ElementNode || isIgnoredHTMLElement(node.Data) {
			continue
		}
		if isInlineHTMLElement(node.Data) {
			pending = append(pending, node)
			continue
		}
		flush()
		out = append(out, h.block(node, depth)...)
	}
	flush()
	return out
}
