package httpapi

import (
	"errors"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/hkjang/muni/internal/handoff"
)

// A claim is a credential, and the endpoint that redeems it carries the claim
// in its path — the one place the request log would otherwise write it.
func TestLogPathHidesTheClaim(t *testing.T) {
	if got := logPath("/api/v1/handoff/claims/AbC123_-xyz"); got != "/api/v1/handoff/claims/{claim}" {
		t.Errorf("logPath = %q", got)
	}
	for _, path := range []string{"/api/v1/handoff/claims", "/handoff", "/api/v1/documents/1"} {
		if got := logPath(path); got != path {
			t.Errorf("logPath(%q) = %q", path, got)
		}
	}
}

// The refusal page names the source that was refused, and the source is a
// value from outside — so it is text on the page, never markup.
func TestHandoffPageEscapesWhatCameFromOutside(t *testing.T) {
	status, title, message := handoffFailure(handoff.ErrNotAllowed, `https://evil.example/<script>alert(1)</script>`)
	if status != 403 {
		t.Fatalf("status = %d", status)
	}
	recorder := httptest.NewRecorder()
	handoffPage(recorder, status, title, message)
	body := recorder.Body.String()
	if strings.Contains(body, "<script>") || !strings.Contains(body, "&lt;script&gt;") {
		t.Errorf("page = %s", body)
	}
	if !strings.Contains(recorder.Header().Get("Content-Type"), "text/html") {
		t.Errorf("Content-Type = %q", recorder.Header().Get("Content-Type"))
	}
	// Every failure has words of its own.
	seen := map[string]bool{}
	for _, err := range []error{handoff.ErrNotAllowed, handoff.ErrBadClaim, handoff.ErrNotFound, handoff.ErrRedirect, handoff.ErrUnsupported, handoff.ErrTooLarge, handoff.ErrUnreachable, errors.New("other")} {
		_, title, _ := handoffFailure(err, "")
		seen[title] = true
	}
	if len(seen) != 6 {
		t.Errorf("%d distinct titles for 8 errors (bad claim and not found share one, unreachable and other share one)", len(seen))
	}
}

func TestFetchNeverAsksAnUnlistedSource(t *testing.T) {
	var calls atomic.Int32
	source := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		w.Header().Set("Content-Type", "text/markdown; charset=utf-8")
		_, _ = w.Write([]byte("# hi"))
	}))
	defer source.Close()
	client := NewClient(http.DefaultTransport)
	_, err := Fetch(context.Background(), client, Config{}, source.URL, "abcdefghijklmnopqrstuvwxyz")
	if !errors.Is(err, ErrNotAllowed) {
		t.Fatalf("err = %v", err)
	}
	if calls.Load() != 0 {
		t.Fatal("an unlisted source was asked")
	}
	// A malformed claim is refused before any request too.
	_, err = Fetch(context.Background(), client, peerList(source.URL), source.URL, "../../etc")
	if !errors.Is(err, ErrBadClaim) || calls.Load() != 0 {
		t.Fatalf("err = %v, calls = %d", err, calls.Load())
	}
	document, err := Fetch(context.Background(), client, peerList(source.URL), source.URL, "abcdefghijklmnopqrstuvwxyz")
	if err != nil || string(document.Body) != "# hi" || document.Format != FormatMarkdown {
		t.Fatalf("document = %+v, err = %v", document, err)
	}
}

func TestFetchDoesNotFollowRedirects(t *testing.T) {
	var followed atomic.Int32
	source := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/elsewhere" {
			followed.Add(1)
		}
		http.Redirect(w, r, "/elsewhere", http.StatusFound)
	}))
	defer source.Close()
	_, err := Fetch(context.Background(), NewClient(http.DefaultTransport), peerList(source.URL), source.URL, "abcdefghijklmnopqrstuvwxyz")
	if !errors.Is(err, ErrRedirect) {
		t.Fatalf("err = %v", err)
	}
	if followed.Load() != 0 {
		t.Fatal("the redirect was followed")
	}
}

func TestFetchCutsOffAnOversizedBody(t *testing.T) {
	source := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/markdown")
		// No Content-Length: the size is only known by reading.
		w.(http.Flusher).Flush()
		chunk := strings.Repeat("a", 1<<20)
		for i := 0; i <= MaxBodyBytes>>20; i++ {
			if _, err := w.Write([]byte(chunk)); err != nil {
				return
			}
		}
	}))
	defer source.Close()
	_, err := Fetch(context.Background(), NewClient(http.DefaultTransport), peerList(source.URL), source.URL, "abcdefghijklmnopqrstuvwxyz")
	if !errors.Is(err, ErrTooLarge) {
		t.Fatalf("err = %v", err)
	}
	declared := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/markdown")
		w.Header().Set("Content-Length", "99999999")
		_, _ = w.Write([]byte("x"))
	}))
	defer declared.Close()
	_, err = Fetch(context.Background(), NewClient(http.DefaultTransport), peerList(declared.URL), declared.URL, "abcdefghijklmnopqrstuvwxyz")
	if !errors.Is(err, ErrTooLarge) {
		t.Fatalf("declared: err = %v", err)
	}
}

func TestFetchRefusesAFormatItCannotRead(t *testing.T) {
	source := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/vnd.openxmlformats-officedocument.presentationml.presentation")
		_, _ = w.Write([]byte("PK"))
	}))
	defer source.Close()
	_, err := Fetch(context.Background(), NewClient(http.DefaultTransport), peerList(source.URL), source.URL, "abcdefghijklmnopqrstuvwxyz")
	if !errors.Is(err, ErrUnsupported) {
		t.Fatalf("err = %v", err)
	}
	gone := httptest.NewServer(http.NotFoundHandler())
	defer gone.Close()
	_, err = Fetch(context.Background(), NewClient(http.DefaultTransport), peerList(gone.URL), gone.URL, "abcdefghijklmnopqrstuvwxyz")
	if !errors.Is(err, ErrNotFound) {
		t.Fatalf("404: err = %v", err)
	}
}

func TestFilenameOfReadsBothForms(t *testing.T) {
	for header, want := range map[string]string{
		`attachment; filename="report.md"`:                                            "report.md",
		`attachment; filename*=UTF-8''2026%EB%85%84%20%EA%B0%9C%ED%8E%B8%EC%95%88.md`: "2026년 개편안.md",
		`attachment; filename="../../x.md"`:                                           "x.md",
		`attachment`:                                                                  "",
		``:                                                                            "",
	} {
		if got := filenameOf(header); got != want {
			t.Errorf("%q: got %q, want %q", header, got, want)
		}
	}
}
